function countFactCalls(n){let c=0;function f(n){c++;if(n<=1)return 1;return n*f(n-1);}f(n);return c;}
function countFibCalls(n){let c=0;function f(n){c++;if(n<=1)return n;return f(n-1)+f(n-2);}f(n);return c;}
console.log('factorial(5) calls:', countFactCalls(5));
console.log('factorial(10) calls:', countFactCalls(10));
console.log('fibonacci(5) calls:', countFibCalls(5));
console.log('fibonacci(10) calls:', countFibCalls(10));
console.log('fibonacci(15) calls:', countFibCalls(15));
console.log('fibonacci(20) calls:', countFibCalls(20));

