let calls = 0;
function fib(n, memo = {}) {
  calls++;
  // TODO: return memo[n] if already computed; store result before returning
  if (n <= 1) return n;
  return fib(n - 1, memo) + fib(n - 2, memo);
}
const result = fib(30);
// naive fib(30) makes ~2.7 million calls; memoized should be well under 200
if (result !== 832040) throw new Error('wrong fib value: ' + result);
if (calls > 200) throw new Error('still exponential: ' + calls + ' calls');
console.log('fib(30) =', result, 'in', calls, 'calls (memoized, O(n))');
